package kvhttp

import "core:bytes"
import "core:net"
import "core:strconv"
import "core:strings"

MAX_HEADER_BYTES :: 64 * 1024
MAX_BODY_BYTES :: 1024 * 1024

Request :: struct {
	method: string,
	path:   string,
	body:   []byte,
}

Parse_Error :: enum {
	None,
	Connection_Closed, // peer went away or timed out; nothing to reply to
	Malformed,         // 400
	Headers_Too_Large, // 431
	Body_Too_Large,    // 413
}

Response :: struct {
	status:       int,
	content_type: string,
	body:         []byte,
}

// read_request reads one HTTP/1.1 request from sock. All memory comes from
// context.allocator, which the caller is expected to scope to the connection.
read_request :: proc(sock: net.TCP_Socket) -> (req: Request, err: Parse_Error) {
	buf := make([dynamic]byte, 0, 4096)
	chunk: [4096]byte

	header_end := -1
	for header_end < 0 {
		n, recv_err := net.recv_tcp(sock, chunk[:])
		if recv_err != nil || n == 0 {
			return {}, .Connection_Closed
		}
		search_from := max(0, len(buf) - 3)
		append(&buf, ..chunk[:n])
		if i := bytes.index(buf[search_from:], {'\r', '\n', '\r', '\n'}); i >= 0 {
			header_end = search_from + i
		} else if len(buf) > MAX_HEADER_BYTES {
			return {}, .Headers_Too_Large
		}
	}

	head := string(buf[:header_end])
	request_line, _, header_block := strings_cut(head, "\r\n")

	method, _, rest := strings_cut(request_line, " ")
	target, _, version := strings_cut(rest, " ")
	if method == "" || target == "" || !strings.has_prefix(version, "HTTP/") {
		return {}, .Malformed
	}
	req.method = method
	req.path = target

	content_length := 0
	for line in strings.split_lines_iterator(&header_block) {
		name, found, value := strings_cut(line, ":")
		if !found {
			return {}, .Malformed
		}
		if strings.equal_fold(strings.trim_space(name), "Content-Length") {
			n, ok := strconv.parse_int(strings.trim_space(value), 10)
			if !ok || n < 0 {
				return {}, .Malformed
			}
			content_length = n
		}
	}

	if content_length > MAX_BODY_BYTES {
		return req, .Body_Too_Large
	}

	body_start := header_end + 4
	already := len(buf) - body_start
	if already >= content_length {
		req.body = buf[body_start:][:content_length]
		return req, .None
	}

	body := make([]byte, content_length)
	copy(body, buf[body_start:])
	for already < content_length {
		n, recv_err := net.recv_tcp(sock, body[already:])
		if recv_err != nil || n == 0 {
			return {}, .Connection_Closed
		}
		already += n
	}
	req.body = body
	return req, .None
}

write_response :: proc(sock: net.TCP_Socket, res: Response) -> net.TCP_Send_Error {
	sb := strings.builder_make(0, 256 + len(res.body))
	strings.write_string(&sb, "HTTP/1.1 ")
	strings.write_int(&sb, res.status)
	strings.write_byte(&sb, ' ')
	strings.write_string(&sb, status_text(res.status))
	// RFC 9110 §8.6: no Content-Length on 204; the connection closes after the head.
	if res.status != 204 {
		strings.write_string(&sb, "\r\nContent-Length: ")
		strings.write_int(&sb, len(res.body))
	}
	if res.content_type != "" {
		strings.write_string(&sb, "\r\nContent-Type: ")
		strings.write_string(&sb, res.content_type)
	}
	strings.write_string(&sb, "\r\nConnection: close\r\n\r\n")
	strings.write_bytes(&sb, res.body)

	_, err := net.send_tcp(sock, sb.buf[:])
	return err
}

status_text :: proc(status: int) -> string {
	switch status {
	case 200: return "OK"
	case 201: return "Created"
	case 204: return "No Content"
	case 400: return "Bad Request"
	case 404: return "Not Found"
	case 405: return "Method Not Allowed"
	case 413: return "Content Too Large"
	case 431: return "Request Header Fields Too Large"
	case 500: return "Internal Server Error"
	}
	return "Unknown"
}

@(private = "file")
strings_cut :: proc(s, sep: string) -> (before: string, found: bool, after: string) {
	if i := strings.index(s, sep); i >= 0 {
		return s[:i], true, s[i + len(sep):]
	}
	return s, false, ""
}

package kvhttp

import "base:runtime"
import "core:fmt"
import "core:mem/virtual"
import "core:net"
import "core:os"
import "core:strconv"
import "core:sys/posix"
import "core:thread"
import "core:time"

IO_TIMEOUT :: 10 * time.Second

Connection :: struct {
	store:  ^Store,
	socket: net.TCP_Socket,
}

main :: proc() {
	if len(os.args) != 2 {
		fmt.eprintln("usage: app <port>")
		os.exit(2)
	}
	port, ok := strconv.parse_int(os.args[1], 10)
	if !ok || port < 1 || port > 65535 {
		fmt.eprintfln("invalid port: %q", os.args[1])
		os.exit(2)
	}

	// Writes to a peer that already hung up must surface as errors, not kill us.
	posix.signal(.SIGPIPE, auto_cast posix.SIG_IGN)

	listener, listen_err := net.listen_tcp({address = net.IP4_Loopback, port = port})
	if listen_err != nil {
		fmt.eprintfln("listen on 127.0.0.1:%d failed: %v", port, listen_err)
		os.exit(1)
	}
	defer net.close(listener)

	store: Store
	store_init(&store, runtime.heap_allocator())
	defer store_destroy(&store)

	for {
		client, _, accept_err := net.accept_tcp(listener)
		if accept_err != nil {
			fmt.eprintfln("accept failed: %v", accept_err)
			continue
		}
		conn := Connection{store = &store, socket = client}
		thread.create_and_start_with_poly_data(conn, serve_connection, self_cleanup = true)
	}
}

// serve_connection handles a single request and closes the socket. Every
// per-request allocation lives in an arena released when the connection ends.
serve_connection :: proc(conn: Connection) {
	defer net.close(conn.socket)

	arena: virtual.Arena
	if virtual.arena_init_growing(&arena) != nil {
		return
	}
	defer virtual.arena_destroy(&arena)
	context.allocator = virtual.arena_allocator(&arena)
	context.temp_allocator = context.allocator

	net.set_option(conn.socket, .Receive_Timeout, IO_TIMEOUT)
	net.set_option(conn.socket, .Send_Timeout, IO_TIMEOUT)

	req, parse_err := read_request(conn.socket)
	res: Response
	switch parse_err {
	case .None:
		res = handle(conn.store, req)
	case .Connection_Closed:
		return
	case .Malformed:
		res = {status = 400}
	case .Headers_Too_Large:
		res = {status = 431}
	case .Body_Too_Large:
		res = {status = 413}
	}
	write_response(conn.socket, res)

	// Half-close and drain anything the client is still sending (e.g. an
	// oversized body) so the kernel doesn't reset the connection before the
	// response is read.
	if parse_err != .None {
		net.shutdown(conn.socket, .Send)
		net.set_option(conn.socket, .Receive_Timeout, time.Second)
		scratch: [16 * 1024]byte
		for {
			n, err := net.recv_tcp(conn.socket, scratch[:])
			if err != nil || n == 0 {
				break
			}
		}
	}
}

package kvhttp

import "core:strings"

KV_PREFIX :: "/kv/"
MAX_KEY_LEN :: 64

handle :: proc(store: ^Store, req: Request) -> Response {
	switch {
	case req.path == "/health":
		if req.method != "GET" {
			return {status = 405}
		}
		return {status = 200, content_type = "text/plain", body = transmute([]byte)string("ok")}

	case req.path == "/kv":
		if req.method != "GET" {
			return {status = 405}
		}
		return {status = 200, content_type = "application/json", body = keys_json(store)}

	case strings.has_prefix(req.path, KV_PREFIX):
		key := req.path[len(KV_PREFIX):]
		if !valid_key(key) {
			return {status = 400}
		}
		switch req.method {
		case "GET":
			value, found := store_get(store, key)
			if !found {
				return {status = 404}
			}
			return {status = 200, content_type = "application/octet-stream", body = value}
		case "PUT":
			created := store_put(store, key, req.body)
			return {status = created ? 201 : 200}
		case "DELETE":
			return {status = store_delete(store, key) ? 204 : 404}
		}
		return {status = 405}
	}
	return {status = 404}
}

valid_key :: proc(key: string) -> bool {
	if len(key) == 0 || len(key) > MAX_KEY_LEN {
		return false
	}
	for c in transmute([]byte)key {
		switch c {
		case 'A' ..= 'Z', 'a' ..= 'z', '0' ..= '9', '_', '-':
		case:
			return false
		}
	}
	return true
}

// keys_json renders the sorted key list as a JSON array. Valid keys never
// contain characters that need escaping.
@(private = "file")
keys_json :: proc(store: ^Store) -> []byte {
	keys := store_keys(store)
	sb := strings.builder_make()
	strings.write_byte(&sb, '[')
	for key, i in keys {
		if i > 0 {
			strings.write_byte(&sb, ',')
		}
		strings.write_byte(&sb, '"')
		strings.write_string(&sb, key)
		strings.write_byte(&sb, '"')
	}
	strings.write_byte(&sb, ']')
	return sb.buf[:]
}

package kvhttp

import "base:runtime"
import "core:slice"
import "core:strings"
import "core:sync"

// Store is a thread-safe in-memory key-value map. Keys and values are owned
// by the store and allocated with its own allocator, independent of the
// per-request allocators used by connection handlers.
Store :: struct {
	mutex:     sync.Mutex,
	entries:   map[string][]byte,
	allocator: runtime.Allocator,
}

store_init :: proc(s: ^Store, allocator := context.allocator) {
	s.allocator = allocator
	s.entries = make(map[string][]byte, allocator)
}

store_destroy :: proc(s: ^Store) {
	for k, v in s.entries {
		delete(k, s.allocator)
		delete(v, s.allocator)
	}
	delete(s.entries)
}

// store_put stores a copy of value under key. Returns true if the key was new.
store_put :: proc(s: ^Store, key: string, value: []byte) -> (created: bool) {
	owned_value := slice.clone(value, s.allocator)

	sync.mutex_guard(&s.mutex)
	if existing, found := &s.entries[key]; found {
		delete(existing^, s.allocator)
		existing^ = owned_value
		return false
	}
	s.entries[strings.clone(key, s.allocator)] = owned_value
	return true
}

// store_get returns a copy of the value for key, allocated with `allocator`.
store_get :: proc(s: ^Store, key: string, allocator := context.allocator) -> (value: []byte, found: bool) {
	sync.mutex_guard(&s.mutex)
	stored := s.entries[key] or_return
	return slice.clone(stored, allocator), true
}

// store_delete removes key. Returns true if it was present.
store_delete :: proc(s: ^Store, key: string) -> (deleted: bool) {
	sync.mutex_guard(&s.mutex)
	owned_key, owned_value := delete_key(&s.entries, key)
	if owned_key == "" && owned_value == nil {
		return false
	}
	delete(owned_key, s.allocator)
	delete(owned_value, s.allocator)
	return true
}

// store_keys returns every key sorted ascending, cloned with `allocator`.
store_keys :: proc(s: ^Store, allocator := context.allocator) -> []string {
	keys: [dynamic]string
	{
		sync.mutex_guard(&s.mutex)
		keys = make([dynamic]string, 0, len(s.entries), allocator)
		for k in s.entries {
			append(&keys, strings.clone(k, allocator))
		}
	}
	slice.sort(keys[:])
	return keys[:]
}
